#include <iostream>
#include <string>
using namespace std;

class Speaker {
public:
    virtual void speak() const = 0;
    virtual ~Speaker() {}
};

class Cat : public Speaker {
    string name;
    int fish;
public:
    Cat(string n, int f) : name(n), fish(f) {}
    void speak() const override {
        cout << name << "：喵～本喵吃了 " << fish << " 条" << endl;
    }
};

class Fish : public Speaker {
    string name;
    int fish;
public:
    Fish(string n, int f) : name(n), fish(f) {}
    void speak() const override {
        cout << name << "：咕噜咕噜～本喵吃了 " << fish << " 条" << endl;
    }
};

class Dog : public Speaker {
    string name;
    int fish;
public:
    Dog(string n, int f) : name(n), fish(f) {}
    void speak() const override {
        cout << name << "：汪！本喵吃了 " << fish << " 条" << endl;
    }
};

int main() {
    int a = 0;
    int b = 0;
    int c = 0;
    cin >> a >> b >> c;

    Cat cat("{catName}", a);
    Fish fish("{fishName}", b);
    Dog dog("{dogName}", c);

    Speaker* roster[3];
    roster[0] = &cat;
    roster[1] = &fish;
    roster[2] = &dog;

    for (int i = 0; i < 3; i++) {
        roster[i]->speak();
    }
    return 0;
}
